WITH filtered AS (SELECT id, customer_id, store_id, order_date, status, channel, amount, shipping_fee, UPPER(channel) AS channel_upper, CAST(amount AS INT) AS amount_int FROM orders WHERE order_date >= TO_DATE('2023-08-09') AND customer_id IN (7, 15, 26)) SELECT DATE_TRUNC('MONTH', order_date) AS activity_month, DATE_TRUNC('QUARTER', order_date) AS quarter_start, SORT_ARRAY(COLLECT_SET(channel)) AS channel_list, MAX(amount_int) AS max_amount_int, SUM(CASE WHEN channel = 'web' THEN amount_int ELSE 0 END) AS web_amount_int FROM filtered GROUP BY DATE_TRUNC('MONTH', order_date), DATE_TRUNC('QUARTER', order_date) ORDER BY web_amount_int DESC NULLS LAST
